import csv
import io
import re


_NUMBER = re.compile(
    r"[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)"
    r"(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)",
    re.IGNORECASE,
)


def _is_number(value: str) -> bool:
    return _NUMBER.fullmatch(value.strip()) is not None


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(
        csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=True,
        )
    )
    expected_width = 2
    first_nonblank = None
    candidates = []

    for index, record in enumerate(records):
        if first_nonblank is None and any(value.strip() for value in record):
            first_nonblank = index
        if len(record) != expected_width:
            continue

        first = record[0].strip()
        if first.startswith("#"):
            first = first[1:].lstrip()
        second = record[1].strip()

        if _is_number(first) and _is_number(second):
            break
        if first and second and not _is_number(first) and not _is_number(second):
            candidates.append(index)
    else:
        index = None

    if candidates:
        header_index = candidates[-1] if index is not None else candidates[0]
    elif first_nonblank is not None:
        header_index = first_nonblank
    else:
        header_index = None

    if header_index is None:
        columns = [f"column_{i}" for i in range(1, expected_width + 1)]
        data = records
    elif index is not None and header_index == index:
        columns = [f"column_{i}" for i in range(1, expected_width + 1)]
        data = records[header_index:]
    else:
        columns = [value.strip() for value in records[header_index]]
        if columns[0].startswith("#"):
            columns[0] = columns[0][1:].lstrip()
        data = records[header_index + 1:]

    width = max(expected_width, len(columns), max(map(len, data), default=0))
    used = set(columns)
    while len(columns) < width:
        base = f"column_{len(columns) + 1}"
        name = base
        suffix = 2
        while name in used:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used.add(name)

    return {
        "columns": columns,
        "rows": [record + [""] * (width - len(record)) for record in data],
    }
